// --->> Aktiv
on({ id: '0_userdata.0.Bewässerung.Aktiv' /* Aktiv */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.Bewässerung.Aktiv').val == false) {
    setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
    setState('0_userdata.0.Bewässerung.Laufzeit' /* Laufzeit */, 0, true);
    setState('0_userdata.0.Bewässerung.Zähler' /* Zähler */, 0, true);
    setState('0_userdata.0.Bewässerung.Restzeit' /* Restzeit */, 0, true);
    setState('0_userdata.0.Bewässerung.PVEinfluss' /* PVEinfluss */, 0, true);
    setState('0_userdata.0.Bewässerung.Timezone' /* Timezone */, 0, true);
    setState('0_userdata.0.Bewässerung.BewässerungAktiv' /* BewässerungAktiv */, false);
    console.debug('--> Deaktiviert');
    await wait(16000);
  } else {
    console.debug('--> Aktiviert');
  }
});
// --->> Error
on({ id: 'linktap.0.03444023004B1200.13414023004B1200.status' /* Device status */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('linktap.0.03444023004B1200.13414023004B1200.status').val == 'Connected') {
    setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
    setStateDelayed('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true, 20000, false);
    console.debug('ERROR - no Connection !');
    sendTo('telegram.0', 'send', {
      text: 'Water/ERROR - no Connection !',
    });
    console.warn('telegram: ' + 'Water/ERROR - no Connection !');
  }
});
on({ id: 'linktap.0.03444023004B1200.13414023004B1200.noWater' /* Device no water */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') == true) {
    setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
    setStateDelayed('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true, 20000, false);
