});
on({ id: 'linktap.0.03444023004B1200.13414023004B1200.fall' /* Device fall */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') == true) {
    setState('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true);
    setStateDelayed('linktap.0.03444023004B1200.13414023004B1200.StopInstantMode' /* Stops instant / eco instant mode */, true, 20000, false);
