/*********************************************************
 * BMS Zellspannungsüberwachung – FINAL + stabiler Trend
 *********************************************************/

const PACKS = [1,2,3,4];
const CELLS = 16;
const BASE = 'javascript.0.BMS';

const DIFF_LIMIT_MV    = 50;     // Alarm-Schwelle
const CALC_INTERVAL_MS = 5000;   // max. 1 Berechnung / 5s

// Trend-Parameter (neu)
const TREND_DELTA_MV = 3;   // Empfindlichkeit
const AVG_WINDOW     = 5;   // Glättung

let cache    = {1:[],2:[],3:[],4:[]};
let diffHist = {1:[],2:[],3:[],4:[]};
let timer    = {1:null,2:null,3:null,4:null};

/* ---------- States anlegen ---------- */
function ensure(id, init, common) {
    if (!existsState(id)) createState(id, init, common);
}

PACKS.forEach(p=>{
    cache[p] = Array(CELLS).fill(null);

    ensure(`${BASE}.Pack${p}.Min_V`,0,{type:'number',unit:'V'});
    ensure(`${BASE}.Pack${p}.Max_V`,0,{type:'number',unit:'V'});
    ensure(`${BASE}.Pack${p}.Diff_mV`,0,{type:'number',unit:'mV'});
    ensure(`${BASE}.Pack${p}.Diff_Avg`,0,{type:'number',unit:'mV'});
    ensure(`${BASE}.Pack${p}.Diff_Alarm`,false,{type:'boolean'});

    // Trend
    ensure(`${BASE}.Pack${p}.Trend`,0,{type:'number',role:'value.direction'});
    ensure(`${BASE}.Pack${p}.Trend_Str`,'→',{type:'string'});
    ensure(`${BASE}.Pack${p}.Trend_Color`,'gray',{type:'string'});
});

/* ---------- Trigger (nur Cache füllen) ---------- */
const trigger = /modbus\.1\.holdingRegisters\.(1|2|3|4)\.400(1[6-9]|2[0-9]|30|31)_Cell_Voltage_(\d+)/;

on({id: trigger, change:'ne'}, obj=>{
    const m = obj.id.match(trigger);
    const p = Number(m[1]);
    const c = Number(m[3]);

    cache[p][c-1] = obj.state.val;

    if (!timer[p]) {
        timer[p] = setTimeout(()=>{
            timer[p] = null;
            calc(p);
        }, CALC_INTERVAL_MS);
    }
});

/* ---------- Berechnung ---------- */
function calc(p) {
    const arr = cache[p];

    // Mindestens 80% der Werte müssen da sein
    const valid = arr.filter(v => v !== null);
    if (valid.length < CELLS * 0.8) return;

    // Min / Max
    let min = Infinity, max = -Infinity;
    for (const v of valid) {
        if (v < min) min = v;
        if (v > max) max = v;
    }

    const diff = max - min;

    /* ---------- Verlauf speichern ---------- */
    diffHist[p].push(diff);
    if (diffHist[p].length > AVG_WINDOW) diffHist[p].shift();

    /* ---------- Durchschnitt (Glättung) ---------- */
    const avg = diffHist[p].reduce((a,b)=>a+b,0) / diffHist[p].length;

    /* ---------- Trend (reaktiv) ---------- */
    let trend = 0;

    if (diffHist[p].length >= 2) {
        const last = diffHist[p][diffHist[p].length - 1];
        const prev = diffHist[p][diffHist[p].length - 2];
        const delta = last - prev;

        if (delta > TREND_DELTA_MV) trend = 1;
        else if (delta < -TREND_DELTA_MV) trend = -1;
    }

    /* ---------- Farbe + Pfeil ---------- */
    let color = 'gray';
    let arrow = '→';

    if (trend === 1) {
        color = 'red';
        arrow = '↑';
    } else if (trend === -1) {
        color = 'green';
        arrow = '↓';
    } else {
        color = 'yellow';
        arrow = '→';
    }

    /* ---------- Ausgabe ---------- */
    setStateChanged(`${BASE}.Pack${p}.Min_V`,  Math.round(min)/1000, true);
    setStateChanged(`${BASE}.Pack${p}.Max_V`,  Math.round(max)/1000, true);
    setStateChanged(`${BASE}.Pack${p}.Diff_mV`, Math.round(diff), true);
    setStateChanged(`${BASE}.Pack${p}.Diff_Avg`, Math.round(avg), true);
    setStateChanged(`${BASE}.Pack${p}.Diff_Alarm`, diff > DIFF_LIMIT_MV, true);

    setStateChanged(`${BASE}.Pack${p}.Trend`, trend, true);
    setStateChanged(`${BASE}.Pack${p}.Trend_Str`, arrow, true);
    setStateChanged(`${BASE}.Pack${p}.Trend_Color`, color, true);

    // Debug (optional)
    // log(`Pack ${p} diff=${diff} avg=${avg.toFixed(1)} trend=${trend}`);
}

(async () => {
    const packs = 4;
    const cells = 16;
    const rootId = 'javascript.0.Gobel';

    // --- Hilfsfunktionen ---
    async function createChannelIfNotExists(parentId, id, name) {
        try { await createChannelAsync(`${parentId}.${id}`, { name }); } catch {}
    }

    async function createStateIfNotExists(parentId, id, name, type, role, unit = '', def = 0) {
        try {
            await createStateAsync(`${parentId}.${id}`, { name, type, role, unit, def });
        } catch {}
    }

    // --- Struktur erstellen ---
    async function createStructure() {
        for (let p = 1; p <= packs; p++) {
            const packId = `Pack_${p}`;
            await createChannelIfNotExists(rootId, packId, `Pack ${p}`);
            await createStateIfNotExists(`${rootId}.${packId}`, 'packAlarm', `Pack ${p} Alarm`, 'boolean', 'indicator', '', false);
            await createStateIfNotExists(`${rootId}.${packId}`, 'lastUpdate', `Letzte Änderung Pack ${p}`, 'string', 'date', '', '');
            for (let c = 1; c <= cells; c++) {
                const cellId = `cell_${c}`;
                await createStateIfNotExists(`${rootId}.${packId}`, `${cellId}_modbus`, `Cell ${c} Modbus`, 'number', 'value.voltage', 'V');
                await createStateIfNotExists(`${rootId}.${packId}`, `${cellId}_mqtt`, `Cell ${c} MQTT`, 'number', 'value.voltage', 'V');
                await createStateIfNotExists(`${rootId}.${packId}`, `${cellId}_diff`, `Cell ${c} Differenz`, 'number', 'value.voltage', 'V');
                await createStateIfNotExists(`${rootId}.${packId}`, `${cellId}_alarm`, `Cell ${c} Alarm`, 'boolean', 'indicator', '', false);
            }
        }
    }

    // --- Differenz berechnen und Alarm setzen ---
    async function compareCell(pack, cell, modbusValue, mqttValue) {
        const diff = Math.abs(modbusValue - mqttValue);
        await setStateAsync(`${rootId}.${pack}.${cell}_diff`, { val: diff, ack: true });
        const alarm = diff > 0.05; // Schwelle 50mV
        await setStateAsync(`${rootId}.${pack}.${cell}_alarm`, { val: alarm, ack: true });
        return alarm;
    }

    async function updatePackAlarm(pack) {
        let packAlarm = false;
        for (let c = 1; c <= cells; c++) {
            const cellAlarm = await getStateAsync(`${rootId}.${pack}.cell_${c}_alarm`);
            if (cellAlarm?.val) packAlarm = true;
        }
        await setStateAsync(`${rootId}.${pack}.packAlarm`, { val: packAlarm, ack: true });
    }

    // --- Initiale Berechnung bei Start ---
    async function initialCalculation() {
        for (let p = 1; p <= packs; p++) {
            const packId = `Pack_${p}`;
            for (let c = 1; c <= cells; c++) {
                const modbusState = await getStateAsync(`modbus.1.holdingRegisters.1.${40016 + c - 1}_Cell_Voltage_${c}`);
                const mqttState = await getStateAsync(`mqtt.0.HELTEC_${p}.cell_${c}.voltage`);
                const modbusVal = modbusState?.val ? modbusState.val / 1000 : 0;
                const mqttVal = mqttState?.val ?? 0;
                await setStateAsync(`${rootId}.${packId}.cell_${c}_modbus`, { val: modbusVal, ack: true });
                await setStateAsync(`${rootId}.${packId}.cell_${c}_mqtt`, { val: mqttVal, ack: true });
                await compareCell(packId, `cell_${c}`, modbusVal, mqttVal);
            }
            await updatePackAlarm(packId);
            await setStateAsync(`${rootId}.${packId}.lastUpdate`, { val: new Date().toISOString(), ack: true });
        }
    }

    // --- MQTT Trigger optimiert: EIN Trigger für alle HELTEC-Zellen ---
    on({ id: /^mqtt\.0\.HELTEC_\d+\.cell_\d+\.voltage$/, change: "any" }, async (obj) => {
        const match = obj.id.match(/^mqtt\.0\.HELTEC_(\d+)\.cell_(\d+)\.voltage$/);
        if (!match) return;

        const packNum = match[1];
        const cellNum = match[2];
        const packId = `Pack_${packNum}`;
        const cellId = `cell_${cellNum}`;
        const mqttVal = obj.state.val ?? 0;
        const modbusState = await getStateAsync(`modbus.1.holdingRegisters.1.${40016 + Number(cellNum) - 1}_Cell_Voltage_${cellNum}`);
        const modbusVal = modbusState?.val ? modbusState.val / 1000 : 0;

        await setStateAsync(`${rootId}.${packId}.${cellId}_mqtt`, { val: mqttVal, ack: true });
        await setStateAsync(`${rootId}.${packId}.${cellId}_modbus`, { val: modbusVal, ack: true });
        await compareCell(packId, cellId, modbusVal, mqttVal);
        await updatePackAlarm(packId);
        await setStateAsync(`${rootId}.${packId}.lastUpdate`, { val: new Date().toISOString(), ack: true });
    });

    console.log('Starte Struktur-Erstellung...');
    await createStructure();
    console.log('Starte initiale Berechnung...');
    await initialCalculation();
    console.log('Script fertig, MQTT-Trigger aktiv.');
})();

// Konfiguration
const numDevices = 4;
const numCells = 16;
const startRegister = 40016;
const UPDATE_INTERVAL_MS = 60000;  // Genau 1x pro Minute (60s)

// 1. INITIALISIERUNG & DATENPUNKT-ERZEUGUNG IN MQTT.2 (Läuft nur 1x beim Start)
for (let d = 1; d <= numDevices; d++) {
    const mqttTopic = `mqtt.2.Gobel.Gobel_${d}_All_Voltages`;

    // extendObject erzwingt das Anlegen/Aktualisieren im fremden Adapter-Verzeichnis
    extendObject(mqttTopic, {
        type: 'state',
        common: {
            name: `Gobel ${d} Alle 16 Zellspannungen als JSON-Liste`,
            type: 'string',
            role: 'json',
            read: true,
            write: true,
            def: '{"value":[]}'
        },
        native: {}
    }, function(err) {
        if (!err) {
            log(`Datenpunkt ${mqttTopic} wurde erfolgreich angelegt/überprüft.`, 'info');
        } else {
            log(`Fehler beim Anlegen von ${mqttTopic}: ${err}`, 'error');
        }
    });
}

// 2. DER MINUTEN-TAKT (Sorgt für die exakte Ausführung alle 60 Sekunden)
setInterval(function() {
    log("Starte minütliches Gobel-BMS Update...", "info");
    for (let d = 1; d <= numDevices; d++) {
        buildAndPublishJson(d);
    }
}, UPDATE_INTERVAL_MS);

// 3. VERARBEITUNG & SENDEN
function buildAndPublishJson(deviceId) {
    const currentVoltages = [];
    const baseId = `modbus.1.holdingRegisters.${deviceId}.`;

    // 16 Werte aus dem Modbus-RAM-Cache lesen
    for (let i = 0; i < numCells; i++) {
        const stateId = `${baseId}${startRegister + i}_Cell_Voltage_${i + 1}`; 
        const state = getState(stateId);

        if (state && state.val !== undefined && state.val !== null) {
            currentVoltages.push(state.val);
        } else {
            currentVoltages.push(0); 
        }
    }

    const jsonPayload = JSON.stringify({ value: currentVoltages });
    const mqttTopic = `mqtt.2.Gobel.Gobel_${deviceId}_All_Voltages`;

    // ack=false triggert den MQTT-Adapter aktiv zum Senden
    setState(mqttTopic, jsonPayload, false);
    log(`Device ${deviceId} an MQTT-Adapter übergeben: ${jsonPayload}`, "info");
}

// Sofort-Start nach 3 Sekunden beim Speichern
setTimeout(function() {
    log("Initialer Skriptstart: Erster Durchlauf...", "info");
    for (let d = 1; d <= numDevices; d++) {
        buildAndPublishJson(d);
    }
}, 3000);

// --- KONFIGURATION ---
const targetFolder = "mqtt.1.Gobel";    // Zielpfad geändert auf Gobel
const batteryCount = 4;                 // Anzahl deiner Gobel-Batterien (1 bis 4)
const cellsPerBattery = 16;             // 16 Zellen pro Batterie

// Funktion zum Erstellen der Datenpunkte via korrektem 'setObject'
function createMqttStates() {
    for (let b = 1; b <= batteryCount; b++) {
        for (let c = 1; c <= cellsPerBattery; c++) {
            let stateId = `${targetFolder}.Gobel_${b}_Cell_${c}`;

            setObject(stateId, {
                type: 'state',
                common: {
                    name: `Gobel ${b} Zelle ${c} Spannung (JSON)`,
                    type: 'string',
                    role: 'text',
                    read: true,
                    write: true
                },
                native: {}
            });
        }
    }
}

// Hauptfunktion zum Synchronisieren der Werte
function syncIndividualVoltages() {
    for (let b = 1; b <= batteryCount; b++) {
        for (let c = 1; c <= cellsPerBattery; c++) {
            let address = 40015 + c; // 40016 für Zelle 1
            let sourceId = `modbus.1.holdingRegisters.${b}.${address}_Cell_Voltage_${c}`;

            if (existsState(sourceId)) {
                let val = getState(sourceId).val;

                // Konvertierung von mV in V
                if (val > 100) val = val / 1000; 
                val = Math.round(val * 1000) / 1000; // Auf 3 Nachkommastellen runden

                // Erstellt das JSON-Format: {"value":3.232}
                let jsonPayload = JSON.stringify({ value: val });
                setState(`${targetFolder}.Gobel_${b}_Cell_${c}`, jsonPayload, true);
            }
        }
    }
}

// 1. Datenpunkte sofort beim Skriptstart anlegen lassen
createMqttStates();

// 2. Werte alle 5 Sekunden aktualisieren
schedule("*/5 * * * * *", syncIndividualVoltages);

// 3. Nachlauf von 1 Sekunde beim Start für den ersten Durchlauf
setTimeout(syncIndividualVoltages, 1000);

