/*******************************************************
 * go-e Charger – Ladesessions Logger (FINAL++)
 * ✔ lesbare Zeit
 * ✔ stabile Erkennung über Ladeleistung
 *******************************************************/

const ROOT = 'javascript.0.goE.sessions';
const ENERGY_STATE = 'go-e.2.loaded_energy_kwh';
const POWER_STATE = 'go-e.2.energy.power';

// Schwellwert ab wann "Laden aktiv"
const POWER_THRESHOLD = 100; // Watt

let sessionActive = false;
let startEnergy = 0;
let startTime = 0;

// Session-ID persistent
createState(`${ROOT}.lastSessionId`, 0, { type: 'number' });

// --- nächste Session-ID ---
function getNextSessionId() {
    let id = getState(`${ROOT}.lastSessionId`).val || 0;
    id++;
    setState(`${ROOT}.lastSessionId`, id, true);
    return 'session_' + id.toString().padStart(3, '0');
}

// --- Start ---
function startSession() {
    startEnergy = getState(ENERGY_STATE).val;
    startTime = Date.now();
    sessionActive = true;

    log('🔌 Ladesession gestartet');
}

// --- Ende ---
function endSession() {
    const endEnergy = getState(ENERGY_STATE).val;
    const endTime = Date.now();

    const energy = Math.max(0, endEnergy - startEnergy);
    const duration = Math.round((endTime - startTime) / 60000);

    const id = getNextSessionId();
    const path = `${ROOT}.${id}`;

    // lesbare Zeiten
    const startReadable = new Date(startTime).toLocaleString();
    const endReadable = new Date(endTime).toLocaleString();

    createState(`${path}.startTime`, startTime, { type: 'number', role: 'value.time' });
    createState(`${path}.startTime_readable`, startReadable, { type: 'string' });

    createState(`${path}.endTime`, endTime, { type: 'number', role: 'value.time' });
    createState(`${path}.endTime_readable`, endReadable, { type: 'string' });

    createState(`${path}.energy_kWh`, energy, { type: 'number', role: 'value.energy', unit: 'kWh' });
    createState(`${path}.duration_min`, duration, { type: 'number', role: 'value', unit: 'min' });

    log(`✅ Session gespeichert: ${id} | ${energy.toFixed(2)} kWh | ${duration} min`);

    sessionActive = false;
}

// --- Trigger über Leistung ---
on({ id: POWER_STATE, change: 'ne' }, (obj) => {

    const power = obj.state.val;

    // START: Leistung steigt über Schwellwert
    if (power > POWER_THRESHOLD && !sessionActive) {
        startSession();
    }

    // STOP: Leistung fällt unter Schwellwert
    if (power <= POWER_THRESHOLD && sessionActive) {
        endSession();
    }
});

'use strict';

const ROOT = '0_userdata.0.Energiemanagement.Batterie';
const CONFIG = '0_userdata.0.Energiemanagement.Config';
const PACKS = [1, 2, 3, 4];
const CELLS = 16;
const invalidReported = { 1: false, 2: false, 3: false, 4: false };

function createOutputStates() {
    for (const pack of PACKS) {
        const base = `${ROOT}.Pack${pack}.BMS_Heltec_Vergleich`;
        createState(`${base}.Alarm`, true, stateCommon('BMS-/HELTEC-Vergleichsalarm', 'boolean', 'indicator.alarm'));
        createState(`${base}.Daten_Gueltig`, false, stateCommon('Alle Vergleichsdaten gueltig', 'boolean', 'indicator'));
        createState(`${base}.Gueltige_Zellen`, 0, stateCommon('Anzahl gueltiger Vergleiche', 'number', 'value'));
        createState(`${base}.Alarm_Zellen`, '', stateCommon('Zellen mit Abweichungsalarm', 'string', 'text'));
        createState(`${base}.Max_Differenz_mV`, 0, stateCommon('Maximale BMS-/HELTEC-Abweichung', 'number', 'value', 'mV'));
        createState(`${base}.Letzte_Aktualisierung`, '', stateCommon('Letzte Aktualisierung', 'string', 'date'));

        for (let cell = 1; cell <= CELLS; cell++) {
            const cellBase = `${base}.Zelle${cell}`;
            createState(`${cellBase}.Differenz_mV`, 0, stateCommon(`Zelle ${cell} Abweichung`, 'number', 'value', 'mV'));
            createState(`${cellBase}.Alarm`, true, stateCommon(`Zelle ${cell} Abweichungsalarm`, 'boolean', 'indicator.alarm'));
        }
    }
}

function stateCommon(name, type, role, unit) {
    const common = { name, type, role, read: true, write: false };
    if (unit) common.unit = unit;
    return common;
}

function configNumber(id, fallback) {
    const state = getState(`${CONFIG}.${id}`);
    const value = state && Number(state.val);
    return Number.isFinite(value) ? value : fallback;
}

function writeChanged(id, value) {
    const current = getState(id);
    if (!current || current.val !== value) setState(id, value, true);
}

function readFreshNumber(id, maxAgeMs) {
    const state = getState(id);
    const value = state && Number(state.val);
    if (!state || !Number.isFinite(value) || value <= 0 || Date.now() - state.ts > maxAgeMs) return null;
    return { value, ts: state.ts };
}

function readHeltecPack(pack, maxAgeMs) {
    const state = getState(`mqtt.0.HELTEC_${pack}.data`);
    if (!state || typeof state.val !== 'string' || Date.now() - state.ts > maxAgeMs) return null;

    try {
        const payload = JSON.parse(state.val);
        if (!payload || !Array.isArray(payload.cells) || payload.cells.length !== CELLS) return null;

        const cells = Array(CELLS).fill(null);
        for (const item of payload.cells) {
            const cell = Number(item && item.cell);
            const voltage = Number(item && item.voltage);
            if (cell >= 1 && cell <= CELLS && Number.isFinite(voltage) && voltage > 0) {
                cells[cell - 1] = voltage;
            }
        }
        return cells.every(value => value !== null) ? { cells, ts: state.ts } : null;
    } catch (error) {
        return null;
    }
}

function updatePack(pack, alarmLimitMv, maxAgeMs) {
    const base = `${ROOT}.Pack${pack}.BMS_Heltec_Vergleich`;
    const alarmCells = [];
    let validCells = 0;
    let maxDiffMv = 0;
    let latestSourceTs = 0;
    const heltecPack = readHeltecPack(pack, maxAgeMs);

    for (let cell = 1; cell <= CELLS; cell++) {
        const register = 40015 + cell;
        const paceId = `modbus.1.holdingRegisters.${pack}.${register}_Cell_Voltage_${cell}`;
        const paceState = readFreshNumber(paceId, maxAgeMs);
        const heltecV = heltecPack && heltecPack.cells[cell - 1];
        const cellBase = `${base}.Zelle${cell}`;

        if (paceState === null || heltecV === null) {
            writeChanged(`${cellBase}.Alarm`, true);
            alarmCells.push(cell);
            continue;
        }

        const paceV = paceState.value / 1000;
        const diffMv = Math.abs(paceV - heltecV) * 1000;
        const alarm = diffMv > alarmLimitMv;
        validCells++;
        latestSourceTs = Math.max(latestSourceTs, paceState.ts, heltecPack.ts);
        maxDiffMv = Math.max(maxDiffMv, diffMv);
        if (alarm) alarmCells.push(cell);

        writeChanged(`${cellBase}.Differenz_mV`, Math.round(diffMv));
        writeChanged(`${cellBase}.Alarm`, alarm);
    }

    const complete = validCells === CELLS;
    writeChanged(`${base}.Gueltige_Zellen`, validCells);
    writeChanged(`${base}.Daten_Gueltig`, complete);
    writeChanged(`${base}.Alarm_Zellen`, alarmCells.join(','));
    writeChanged(`${base}.Max_Differenz_mV`, Math.round(maxDiffMv));
    writeChanged(`${base}.Alarm`, !complete || alarmCells.length > 0);
    if (latestSourceTs > 0) writeChanged(`${base}.Letzte_Aktualisierung`, new Date(latestSourceTs).toISOString());

    if (!complete) {
        if (!invalidReported[pack]) {
            log(`Batterie_BMS_Heltec_Vergleich: Pack ${pack} hat nur ${validCells} von ${CELLS} gueltigen Vergleichen.`, 'warn');
            invalidReported[pack] = true;
        }
    } else {
        invalidReported[pack] = false;
    }
}

function updateAll() {
    try {
        const alarmLimitMv = configNumber('Batterie_BMS_Heltec_Alarm_mV', 50);
        const maxAgeMs = configNumber('Batterie_Zelldaten_Max_Alter_Sekunden', 300) * 1000;
        for (const pack of PACKS) updatePack(pack, alarmLimitMv, maxAgeMs);
    } catch (error) {
        log(`Batterie_BMS_Heltec_Vergleich Fehler: ${error.message}`, 'warn');
    }
}

createOutputStates();
schedule('*/30 * * * * *', updateAll);
log('Batterie-BMS-/HELTEC-Vergleich ist gestartet.', 'info');

'use strict';

const ROOT = '0_userdata.0.Energiemanagement.Batterie';
const CONFIG = '0_userdata.0.Energiemanagement.Config';
const PACKS = [1, 2, 3, 4];
const CELLS = 16;
const HISTORY_LENGTH = 5;
const TREND_THRESHOLD_MV = 3;
const diffHistory = { 1: [], 2: [], 3: [], 4: [] };
const invalidReported = { 1: false, 2: false, 3: false, 4: false };

function createOutputStates() {
    for (const pack of PACKS) {
        const base = `${ROOT}.Pack${pack}.Zellspannung`;
        createState(`${base}.Min_V`, 0, stateCommon('Minimale Zellspannung', 'number', 'value.voltage', 'V'));
        createState(`${base}.Max_V`, 0, stateCommon('Maximale Zellspannung', 'number', 'value.voltage', 'V'));
        createState(`${base}.Differenz_mV`, 0, stateCommon('Zellspannungsdifferenz', 'number', 'value', 'mV'));
        createState(`${base}.Durchschnitt_mV`, 0, stateCommon('Geglaettete Zellspannungsdifferenz', 'number', 'value', 'mV'));
        createState(`${base}.Alarm`, true, stateCommon('Zellspannungsalarm', 'boolean', 'indicator.alarm'));
        createState(`${base}.Daten_Gueltig`, false, stateCommon('Alle Zelldaten gueltig', 'boolean', 'indicator'));
        createState(`${base}.Gueltige_Zellen`, 0, stateCommon('Anzahl gueltiger Zellen', 'number', 'value'));
        createState(`${base}.Trend`, 0, stateCommon('Trend der Zellspannungsdifferenz', 'number', 'value.direction'));
        createState(`${base}.Trend_Text`, 'stabil', stateCommon('Trend als Text', 'string', 'text'));
        createState(`${base}.Letzte_Aktualisierung`, '', stateCommon('Letzte Aktualisierung', 'string', 'date'));
    }
}

function stateCommon(name, type, role, unit) {
    const common = { name, type, role, read: true, write: false };
    if (unit) common.unit = unit;
    return common;
}

function configNumber(id, fallback) {
    const state = getState(`${CONFIG}.${id}`);
    const value = state && Number(state.val);
    return Number.isFinite(value) ? value : fallback;
}

function writeChanged(id, value) {
    const current = getState(id);
    if (!current || current.val !== value) setState(id, value, true);
}

function readPaceCell(pack, cell, maxAgeMs) {
    const register = 40015 + cell;
    const id = `modbus.1.holdingRegisters.${pack}.${register}_Cell_Voltage_${cell}`;
    const state = getState(id);
    const value = state && Number(state.val);
    if (!state || !Number.isFinite(value) || value <= 0 || Date.now() - state.ts > maxAgeMs) return null;
    return { value, ts: state.ts };
}

function updatePack(pack, alarmLimitMv, maxAgeMs) {
    const base = `${ROOT}.Pack${pack}.Zellspannung`;
    const cells = [];

    for (let cell = 1; cell <= CELLS; cell++) {
        const cellState = readPaceCell(pack, cell, maxAgeMs);
        if (cellState !== null) cells.push(cellState);
    }

    const complete = cells.length === CELLS;
    const latestSourceTs = cells.reduce((latest, cell) => Math.max(latest, cell.ts), 0);
    writeChanged(`${base}.Gueltige_Zellen`, cells.length);
    writeChanged(`${base}.Daten_Gueltig`, complete);
    if (latestSourceTs > 0) writeChanged(`${base}.Letzte_Aktualisierung`, new Date(latestSourceTs).toISOString());

    if (!complete) {
        writeChanged(`${base}.Alarm`, true);
        if (!invalidReported[pack]) {
            log(`Batterie_Zellspannungen: Pack ${pack} hat nur ${cells.length} von ${CELLS} gueltigen Zellen.`, 'warn');
            invalidReported[pack] = true;
        }
        return;
    }
    invalidReported[pack] = false;

    const values = cells.map(cell => cell.value);
    const minMv = Math.min(...values);
    const maxMv = Math.max(...values);
    const diffMv = maxMv - minMv;
    const history = diffHistory[pack];
    history.push(diffMv);
    if (history.length > HISTORY_LENGTH) history.shift();

    const averageMv = history.reduce((sum, value) => sum + value, 0) / history.length;
    let trend = 0;
    if (history.length >= 2) {
        const delta = history[history.length - 1] - history[history.length - 2];
        if (delta > TREND_THRESHOLD_MV) trend = 1;
        if (delta < -TREND_THRESHOLD_MV) trend = -1;
    }

    writeChanged(`${base}.Min_V`, Math.round(minMv) / 1000);
    writeChanged(`${base}.Max_V`, Math.round(maxMv) / 1000);
    writeChanged(`${base}.Differenz_mV`, Math.round(diffMv));
    writeChanged(`${base}.Durchschnitt_mV`, Math.round(averageMv));
    writeChanged(`${base}.Alarm`, diffMv > alarmLimitMv);
    writeChanged(`${base}.Trend`, trend);
